return {
  [ [[v5748eaic9vic]] ] = { t = [[内在加值物品]], q = [=[《核心规则书》中有几件昂贵的物品，比如[[静思卷册]]，能提供属性值的内在加值。这些物品在探索者协会组织游戏中如何运作？]=], a = [[如果你在冒险中发现这类物品，它的加值持续到该冒险结束。但如果你花钱购买并使用该物品，加值就是永久的。请把这些加值记录在你的记录单上。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vic]], cat = [[PFS]], ai = true, pages = { [[PFS：特殊规则]] } },
  [ [[v5748eaic9vi9]] ] = { t = [[升级物品]], q = [[升级武器、防具和奇物的规则是什么？]], a = [[只要新物品占用同一个物品栏位、由相同的材料制成、外形大体相同，并且具备原物品的全部能力，你就可以把一件武器、防具或奇物升级成另一件。例如，你可以把一把+1长剑升级成+1冻寒长剑，或把+1抗力披风升级成+2抗力披风。你也可以把魔法武器或防具升级成某件特定名称的武器或防具，比如把+1混织铁甲升级成幸运护甲。再举个例子，你可以把+2极限敏捷腰带升级成《极限宝具》中的黄鼠狼腰带，它在提供+2敏捷增强加值之外还有其他好处。

升级魔法物品时，支付新物品与原物品的差价即可。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vi9]], cat = [[PFS]], ai = true, pages = { [[PFS：特殊规则]], [[制造魔法物品]] } },
  [ [[v5748eaic9vhm]] ] = { t = [[交换与抄录法术]], q = [[我的准备型施法者能向其他PC学习法术吗？冒险中发现的卷轴获得法术又如何？]], a = [=[玩家欢迎在冒险过程中互相交换法术。但他们仍须遵守《核心规则书》和各自职业描述中的一切常规规则（例如，[[炼金术师]]可以从[[法师]]那里抄录法术，反之则不行），并且不得拖慢游戏进度。

同样，冒险中发现的卷轴可以按常规规则用来向法术书以及类似的职业能力（例如[[女巫]]的魔宠）添加法术。冒险中这样使用的卷轴不必购买，但仍如常被消耗。

无论哪种方式，GM都应当在目睹成功的技能检定之后，在受影响玩家的记录单上签字确认所获得的法术。其他一切获得新法术的方式（如升级，或花钱购买NPC法术书的使用权）仍按《核心规则书》和相关职业描述中所述执行。冒险之间，PC总能找到NPC来教授任何其角色合法可学的法术。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhm]], cat = [[PFS]], ai = true, pages = { [[魔法]], [[PFS：特殊规则]] } },
  [ [[v5748eaic9vhh]] ] = { t = [[向NPC学习法术的费用]], q = [[我的准备型施法者向NPC学习一个法术要花多少钱？]], a = [[NPC会收取教授法术的费用。该费用始终等于把该法术写入法术书的花费的一半（见《核心规则书》第219页的“将新法术写入法术书”）。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhh]], cat = [[PFS]], ai = true, pages = { [[魔法]] } },
  [ [[v5748eaic9vht]] ] = { t = [[非法师使用法术书]], q = [[我不是法师，但我的某个角色选项提到了使用法术书。我能拥有自己的法术书吗？]], a = [=[可以。如果你角色的任何能力提到使用法术书，你可以购买法术书，并按《核心规则书》魔法一章中向法术书添加新法术的标准规则，把法术抄录进去。例如，拥有[[秘示域/知识秘示域|知识秘示域]]和奥术学者启示的[[先知]]可以购买并填写自己的法术书（《进阶玩家指南》第49页）。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vht]], cat = [[PFS]], ai = true, pages = { [[魔法]] } },
  [ [[v5748eaic9vhj]] ] = { t = [[炼金术师与调查员的制作]], q = [[炼金术师和调查员在探索者协会组织游戏中如何制作物品？]], a = [=[[[炼金术师]]和[[调查员]]可以使用[[工艺]]（炼金术）技能，借助炼金术能力来制造物品。请遵循《核心规则书》第91–93页的工艺规则，以及炼金术师炼金术能力的描述。所制造的任何物品都必须如实记录在该模组的记录单上。炼金术师和调查员被视为随身携带了必要的物品和工具，可以利用现有资源制造炼金物品。如果他们有可作为据点的地方，则可以使用[[炼金师工作台]]，使其工艺（炼金术）检定获得+2加值。炼金术师和调查员不得出售自己制造的任何物品，也不得与其他PC交易。不过，他们可以让其他PC借用或使用自己制造的物品（只要所用的职业能力允许）。炼金术师和调查员可以用工艺（炼金术）制造他们在记录单上获得购买权的物品，只要该记录单没有限制他们购买这些物品的次数。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhj]], cat = [[PFS]], ai = true, pages = { [[炼金术师]], [[调查员]] } },
  [ [[v5748eaic9vhq]] ] = { t = [[混血术士与狂野血统]], q = [[我能同时选择狂野血统和混血术士这两个术士变体职业吗？]], a = [[不能。关于变体职业叠加的更多信息，请参见这条[https://paizo.com/paizo/faq/v5748nruor1fn#v5748eaic9thg 《进阶玩家指南》FAQ]。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhq]], cat = [[PFS]], ai = true, pages = { [[变体职业]], [[混血术士]], [[狂野血统]] } },
  [ [[v5748eaic9wha]] ] = { t = [[超小型及以下的防具武器]], q = [[我能购买超小型及以下体型的防具和武器吗？]], a = [[可以。在组织游戏中，这类防具和武器的价格与对应的小型防具和武器相同，包括特殊材料的额外花费。]], book = [[探索者协会组织游戏指南6.0]], date = [[2018/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9wha]], cat = [[PFS]], ai = true, pages = { [[装备]] } },
  [ [[v5748eaic9whe]] ] = { t = [[动物伙伴体型增大后的护甲]], q = [[我的动物伙伴体型长大了，不再穿得下我给它买的护甲。我必须卖掉旧护甲，再给它买一套新的吗？]], a = [[不必。你可以补足差价，让护甲改装得适合体型更大的伙伴。如果没有差价（例如小型生物长成中型），你可以在两次冒险之间免费改装护甲。]], book = [[探索者协会组织游戏指南6.0]], date = [[2018/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9whe]], cat = [[PFS]], ai = true, pages = { [[坐骑护甲]] } },
  [ [[v5748eaic9wh8]] ] = { t = [[钱财与战利品的重量]], q = [[我角色的钱财会让她负重吗？冒险中找到的财宝呢？]], a = [[在组织游戏中，我们假定角色以宝石、信用凭据或其他基本没有重量的形式携带财富。

冒险过程中，财宝的重量可能有关系——例如，一队力量值低的角色也许无法轻易在遭遇之间搬运他们的发现——但一般假定角色在冒险结束时能把找到的所有物品带回探索者协会。除非模组另有说明，物品重量不影响玩家在记录单上获得的奖励。]], book = [[探索者协会组织游戏指南6.0]], date = [[2018/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9wh8]], cat = [[PFS]], ai = true, pages = { [[装备]] } },
  [ [[v5748eaic9vhs]] ] = { t = [[失聪者读唇]], q = [[失聪的先知（或其他失聪的PC）要怎么做才能读唇？]], a = [=[在探索者协会组织游戏中，任何在[[语言学]]上投入1点技能等级的PC，可以选择学会以自己所知的所有语言读唇，而不是学习一门新语言。她无法用读唇来解读自己不懂的语言。当读取10尺内正在说话的生物的唇语、且光照条件正常时，读唇者无需进行任何技能检定。在更困难的情形下，读唇者必须进行[[察觉]]检定，DC由GM决定。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhs]], cat = [[PFS]], ai = true, pages = { [[先知诅咒/失聪]] } },
  [ [[v5748eaic9vhu]] ] = { t = [[观命术的效果]], q = [=[[[观命术]]能给我多少好处？]=], a = [[观命术只分析你察觉到的生物。你必须能看见该生物，才能立刻得知它是已经死亡、奄奄一息（活着但受了伤，剩余生命值不超过3点）、死里逃生（活着，生命值4点或更高）、健康、不死生物，还是无所谓死活（如构装生物）。对于你没有注意到的生物，该法术完全不会给你任何信息。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhu]], cat = [[PFS]], ai = true, pages = { [[观命术]] } },
  [ [[v5748eaic9vhn]] ] = { t = [[混血术士与龙脉术士]], q = [=[《极限魔法》中的[[混血术士]]能选择[[龙脉术士]]进阶职业吗？]=], a = [=[可以，只要她所选的血统之一是[[术士血统/龙脉血统|龙脉血统]]。同样，龙脉术士之后也可以获得混血术士等级，只要她选择的血统之一是龙脉血统。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhn]], cat = [[PFS]], ai = true, pages = { [[龙脉术士]], [[混血术士]] } },
  [ [[v5748eaic9vhp]] ] = { t = [[交易大师]], q = [[《探索者协会战地指南》中的“交易大师”声望奖励究竟如何运作？]], a = [=[该虚衔的措辞表明，折扣只适用于购买，不包括升级物品。举例来说，如果你一次性购买一件+2[[秘银]]胸甲，就能对该物品的全部价格享受折扣。如果你用折扣购买了一件非魔法的秘银胸甲，那么把它升级成+1秘银胸甲时，你必须支付完整的1000gp差价。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhp]], cat = [[PFS]], ai = true, pages = { [[PFS：派系]] } },
  [ [[v5748eaic9wh9]] ] = { t = [[贴身防具]], q = [[贴身防具附魔在探索者协会中如何运作？]], a = [[贴身防具可以把形态与体型的组合改成任何价值相等或更低的组合。例如，为超大型双足生物（价格×4）购买的贴身防具，也适合任何更小体型的双足或四足生物；而为超大型四足生物（价格×8）购买的贴身防具，可以适合巨型类人生物（价格×8）或任何超大型及以下的生物。注意，当缩小到超小型或更小时，贴身防具提供的护甲加值会像该体型的防具一样通常减半。]], book = [[探索者协会组织游戏指南6.0]], date = [[2018/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9wh9]], cat = [[PFS]], ai = true, pages = { [[贴身]] } },
  [ [[v5748eaic9vhd]] ] = { t = [[购买的动物是否受过训练]], q = [[购买的动物是已经完全训练好的，还是需要我自己训练？]], a = [=[《核心规则书》第97–98页的[[驯养动物]]条目详细说明了哪些动物受过训练——也就是说，某些骑乘马和骑乘用犬受过训练，但它们只受过载着骑手进入战斗的训练。其他所有动物想要学会额外的技巧，都要遵循驯养动物的规则。更多细节见《核心规则书》第159页的“坐骑与相关装备”表。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhd]], cat = [[PFS]], ai = true, pages = { [[驯养动物]] } },
  [ [[v5748eaic9vhc]] ] = { t = [[教授动物技巧]], q = [[我要怎么用驯养动物教动物技巧？]], a = [[只要你遵循《核心规则书》第97–98页的驯养动物规则，就可以教任何动物一个技巧。GM必须观察你的驯养动物检定，并在该模组的记录单上为动物学会的技巧签上姓名首字母。当拥有德鲁伊、游侠等级、或其他任何提供动物伙伴的职业等级的角色首次获得动物伙伴时，该动物进入游戏时就已掌握其最大数量的技巧（由动物伙伴的智力和该角色的有效德鲁伊等级决定）。如果该角色因任何原因更换动物伙伴，新动物起始时不会任何技巧，只有根据PC有效德鲁伊等级给予的额外技巧除外。每个模组中，你可以尝试训练动物伙伴的次数等于你在驯养动物技能上的技能等级数。每次成功可以教会动物一个技巧；失败的尝试也计入每个模组允许的训练次数总数，并且在下一个模组之前你不能再尝试教同一个技巧。或者，只要你在驯养动物上的技能等级足以训练动物学会某项任务所含的每个技巧，你也可以训练一只动物承担某个单一任务。你可以对教动物伙伴技巧的驯养动物检定取10。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhc]], cat = [[PFS]], ai = true, pages = { [[驯养动物]], [[动物伙伴]] } },
  [ [[v5748eaic9vhb]] ] = { t = [[自创技巧]], q = [[我能创造新技巧并教给我的动物伙伴吗？]], a = [=[不能。新技巧需要GM临场创造新机制，因此不适用于探索者协会组织游戏。如果某个技巧出现在规则中的某处，即使它没有列在《核心规则书》第97页的驯养动物技能之下，你也可以教给动物。例如，[[凌空而行]]法术明确规定，你可以教动物伙伴一个技巧，让它使用该法术赋予的能力在空中行走。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vhb]], cat = [[PFS]], ai = true, pages = { [[驯养动物]] } },
  [ [[v5748eaic9whd]] ] = { t = [[让伙伴喝药水]], q = [[如果我想让我的动物、植物或害虫伙伴喝药水，需要通过驯养动物检定来强迫它吗？]], a = [[不需要。如果你手持药水并与伙伴相邻，你的伙伴可以在它的回合以一个标准动作喝下药水。具有双足（有手）体型的动物伙伴可以自己取出药水。]], book = [[探索者协会组织游戏指南6.0]], date = [[2018/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9whd]], cat = [[PFS]], ai = true, pages = { [[驯养动物]] } },
  [ [[v5748eaic9vi2]] ] = { t = [[哈罗牌与线上游戏]], q = [[一些以哈罗牌为主题的规则选项要求我拥有一副哈罗牌。这些选项在线上游戏中如何运作？]], a = [=[你仍须拥有一副[[哈罗牌(物品)|哈罗牌]]才能使用这些选项。不过，你可以用骰子代替卡牌来决定结果，这样更便于与GM分享。每当你需要翻一张牌时，改为掷1d10决定其阵营（1=守序善良，2=守序中立，3=守序邪恶，4=中立善良，5=绝对中立，6=中立邪恶，7=混乱善良，8=混乱中立，9=混乱邪恶），并掷1d6决定该牌对应的属性值（1=力量，2=敏捷，3=体质，4=智力，5=感知，6=魅力）。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vi2]], cat = [[PFS]], ai = true, pages = { [[哈罗牌(物品)]] } },
  [ [[v5748eaic9vie]] ] = { t = [[智能物品]], q = [[探索者协会组织游戏中关于智能物品的规则是什么？]], a = [=[一名PC可以同时拥有并使用多件智能魔法物品。

PC可以使用[[使用魔法装置]]技能模仿另一种阵营，以避免在使用智能魔法物品时承受负向等级。PC必须在冒险开始时进行此检定。无论成功还是失败，结果都在整场冒险期间持续有效。此外，除非PC做出某种严重违背物品阵营或目标的行为，否则该阵营的所有智能物品对该PC都正常运作。

当PC持有与自己阵营不相容（无论是天生阵营还是模仿的阵营）的智能物品时，物品与PC之间会产生人格冲突（《核心规则书》第535页）。如果PC的意志豁免成功，该物品在24小时内正常运作。如果失败，物品会迫使他或她把它收起来24小时。

T1–5冒险（以及类似的冒险，如T1–2冒险和T1任务系列）中发现的智能物品，通常会免除PC拿起不相容物品时本应受到的负向等级。这不仅避免了1级PC因触碰智能物品而死亡，也让PC们能在冒险中享受该物品，并在之后再选择是否购买它（以及随之而来的阵营后果）。]=], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh#v5748eaic9vie]], cat = [[PFS]], ai = true, pages = { [[智能物品]] } },
