  [ [[n527]] ] = { t = [[精工转化的数量限制]], q = [=[《探索者协会组织游戏指南》说我只能把一份[[精工转化]]法术的效果从一场冒险带到另一场。如果我对一件处于精工转化效果下的物品附魔，会怎样？]=], a = [[被附魔的物品不再被视为处于精工转化的效果之下，因此不计入一份该法术的限制。]], book = [[探索者协会组织游戏指南6.0]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1hh]], cat = [[PFS]], ai = true, pages = { [[精工转化]], [[PFS：特殊规则]] } },
